# -*- coding: utf-8 -*-
"""docs/5.5-验收清单.docx —— 按 game-docs-and-sheets-inventory.md 5.5 写。

清单要求：每个阶段一组勾选项，对应 game-project-plan.md 的出口判据。
阶段 4 的 7 条来自 game-project-plan.md「检查清单」原文。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "5.5-验收清单.docx")


def stage(doc, num, name, exit_crit, rows, verdict):
    k.h1(doc, num, f"{name}　出口：{exit_crit}")
    k.table(doc, ["☐", "检查项", "状态", "证据 / 差在哪"], rows, [1.0, 8.0, 2.4, 8.0], size=9)
    k.para(doc, verdict)


def main():
    doc = k.new_doc("5.5 验收清单 · v0.1 · 2026-11-04")
    k.title(
        doc,
        "电竞选手模拟器 · 验收清单",
        "八个阶段逐条打勾 · v0.1 · 2026-11-04",
    )
    k.note(
        doc,
        "对应 `game-project-plan.md` 的出口判据。状态只有四种：**✅ 过了 / ❌ 没过 / ⚠ 跳过（有理由） / — 还没到**。"
        "打勾的前提是「有证据」，没有证据的一律算 ❌。",
    )

    # ---------------- 阶段 0 ----------------
    stage(
        doc, "阶段 0", "立项",
        "能回答「玩家为什么还想再来一局」",
        [
            ["☐", "一句话说清玩什么", "✅", "「LOL 职业选手 8 年生涯，一周 1–1.5 小时」"],
            ["☐", "目标玩家是谁", "✅", "虎扑 / LPL 观众，认梗、认选手"],
            ["☐", "再来一局的理由", "✅", "不同分路 + 不同结局 + 梗事件随机；但**没做过留存验证**"],
            ["☐", "不做什么", "✅", "1.3 表 6 的 10 条"],
        ],
        "结论：立项阶段过，但「再来一局」是设计假设，不是观测结果。",
    )

    # ---------------- 阶段 1 ----------------
    stage(
        doc, "阶段 1", "纸面原型",
        "自己连玩 10 局不腻",
        [
            ["☐", "纸面/表格走通一局", "⚠", "**跳过**：直接写了可玩原型"],
            ["☐", "10 局不腻", "⚠", "用 120 种排法 × 4 组种子的批量模拟替代（看数值，不看手感）"],
            ["☐", "记录替代方案", "✅", "1.4 表 4 已写明跳过与替代"],
        ],
        "结论：跳过，有替代与记录。**代价**：手感类问题（无聊、节奏拖）没在纸面阶段暴露。",
    )

    # ---------------- 阶段 2 ----------------
    stage(
        doc, "阶段 2", "可玩原型",
        "陌生人不看说明能走完一局",
        [
            ["☐", "自己能走完一局", "✅", "8 年 → 结局，冒烟脚本走通了第 1 周"],
            ["☐", "不看说明能懂", "❌", "**从没让陌生人试过**"],
            ["☐", "三格 / 抽事件 / 比赛 / 结周 能连起来", "✅", "`reduce.ts` 的结周流程"],
            ["☐", "禁止在本阶段美化", "❌", "本阶段做了 UI（提交 `acc53c8`/`92de93b`），破了纪律"],
        ],
        "结论：**没过**。唯一硬缺口是「陌生人盲测」，而且本阶段偷偷做了美化，纪律没守住。",
    )

    # ---------------- 阶段 3 ----------------
    stage(
        doc, "阶段 3", "数值调优",
        "有数据证明不存在胜率 >80% 的无脑解",
        [
            ["☐", "批量模拟能跑", "✅", "`npm run batch`，120 种排法 × 4 种子 × 240 周"],
            ["☐", "没有 >80% 胜率的无脑解", "❌", "**健身速通**：先刷 20 次健身比老实打快约 1 年；上分必带 → 前十名全含「上分+训练赛」"],
            ["☐", "成长曲线落在目标区间", "⚠", "目标是 3–4 年全 90+，最优解 2.3 年 → 偏快"],
            ["☐", "数值表与代码一致", "❌", "手抄双写，没有 gen:config（3.2 第 7 节）"],
        ],
        "结论：**没过**。模拟做了，但结论是「有无脑解」，且没改到过。这条是首发前最该补的（W4.2 之前）。",
    )

    # ---------------- 阶段 4 ----------------
    stage(
        doc, "阶段 4", "表现与适配",
        "下面 7 条逐条过完",
        [
            ["☐", "视觉层级：一屏一个焦点", "⚠", "有层级，但字号 7 级（2.6 要求 3 级）"],
            ["☐", "四态齐全：默认/按下/加载/空态", "❌", "**加载态 10 屏全缺**，空态只有事件池空"],
            ["☐", "触摸目标 ≥44px", "✅", "行动按钮 min-height 48px"],
            ["☐", "320px 不横向溢出", "⚠", "只有无头模拟，没真机"],
            ["☐", "刘海屏安全区", "✅", "`env(safe-area-inset-bottom)` 已用"],
            ["☐", "点了必须有反应", "✅", "每次点击全量重渲染"],
            ["☐", "战绩卡一键复制 + 失败兜底", "❌", "**复制功能没做**，战绩卡现在是纯文本显示"],
        ],
        "结论：**没过**。7 条里 3 条 ✅、2 条 ⚠、2 条 ❌（加载态、复制兜底）。",
    )

    # ---------------- 阶段 5 ----------------
    stage(
        doc, "阶段 5", "真人测试",
        "列出 ≥3 个你没预料到的问题",
        [
            ["☐", "找 3–5 个真人玩", "⚠", "**跳过**：用户明确「个人原因无法完成」"],
            ["☐", "旁边看着、不解释不提示", "—", "无测试，无从执行"],
            ["☐", "记原话不解释", "—", "同上"],
            ["☐", "三个人说同一件事才算问题", "—", "同上"],
        ],
        "结论：**跳过，且不可用 AI 替代**。这条缺口最大的后果是：难度曲线与手感至今无人验证（见 4.3 的 R2）。",
    )

    # ---------------- 阶段 6 ----------------
    stage(
        doc, "阶段 6", "发布",
        "陌生人能打开链接玩完一局",
        [
            ["☐", "线上链接可访问", "—", "还没投稿"],
            ["☐", "手机能玩", "❌", "真机 0 次（5.1）"],
            ["☐", "分享卡能复制", "❌", "分享与战绩卡复制都没做"],
            ["☐", "错误有兜底提示", "❌", "没有错误边界；localStorage 被禁会静默丢档"],
            ["☐", "无外部依赖被墙", "✅", "零请求"],
            ["☐", "控制台无报错", "✅", "冒烟脚本已断言"],
            ["☐", "隐私/年龄分级说明", "❌", "没有"],
        ],
        "结论：**未开始**。7 条里 2 条 ✅（而且是不需要努力的那 2 条）。",
    )

    # ---------------- 阶段 7 ----------------
    stage(
        doc, "阶段 7", "迭代一轮",
        "能用数据说明这版比上版好",
        [
            ["☐", "有埋点/指标", "—", "没有（6.3 为 S 可选）"],
            ["☐", "能对比两版", "—", "没有数据来源"],
        ],
        "结论：未开始。",
    )

    # ---------------- 汇总 ----------------
    k.h1(doc, "汇总", "现在到底卡在哪")
    k.table(
        doc,
        ["阶段", "状态", "一句话"],
        [
            ["0 立项", "✅ 过", "设计假设成立，但未验证"],
            ["1 纸面原型", "⚠ 跳过", "有替代与记录"],
            ["2 可玩原型", "❌ 没过", "陌生人盲测 0 次"],
            ["3 数值调优", "❌ 没过", "健身速通这个无脑解还在"],
            ["4 表现适配", "❌ 没过", "加载态与战绩卡复制没做"],
            ["5 真人测试", "⚠ 跳过", "不可替代，只能接受风险"],
            ["6 发布", "— 未开始", "卡在真机"],
            ["7 迭代", "— 未开始", "—"],
        ],
        [4.0, 3.6, 12.4],
        size=9,
    )
    k.para(
        doc,
        "**最省力的补齐顺序**：先做阶段 4 的两条 ❌（加载态、复制兜底，都是纯前端），再做阶段 3 的健身漏洞（一次数值改动），"
        "最后才是阶段 2/6 的真机——因为真机只能你自己跑。",
    )

    doc.save(OUT)
    print("saved", OUT)


if __name__ == "__main__":
    main()
